INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(62038, 50, 0, 'The destiny of our clan is set in stone, you can not change fate.', 12, 0, 0, 0, 0, 0, 0, 0, 'Elder Hollowblood - Dragonmaw Retreat - Elder Hollowblood - Aggro Line'),
(62038, 51, 0, 'Behold, the power of the elements!', 12, 0, 0, 0, 0, 0, 0, 0, 'Elder Hollowblood - Dragonmaw Retreat - Elder Hollowblood - 50% Health Line'),
(62038, 52, 0, 'My legacy...', 12, 0, 0, 0, 0, 0, 0, 0, 'Elder Hollowblood - Dragonmaw Retreat - Elder Hollowblood - Death Line'),
(62067, 50, 0, 'You won\'t interrupt my plans...', 14, 0, 0, 0, 0, 0, 0, 0, 'Web Master Torkon - Dragonmaw Retreat - Web Master Torkon - Aggro Line'),
(62067, 51, 0, 'The brood will live on, my work will not end here!', 14, 0, 0, 0, 0, 0, 0, 0, 'Web Master Torkon - Dragonmaw Retreat - Web Master Torkon - 50% Health Line'),
(62067, 52, 0, 'Pointless...', 14, 0, 0, 0, 0, 0, 0, 0, 'Web Master Torkon - Dragonmaw Retreat - Web Master Torkon - Death Line'),
(62068, 50, 0, 'Unidentified intruder detected.', 14, 0, 0, 0, 0, 0, 0, 0, 'Slagfist Destroyer - Dragonmaw Retreat - Slagfist Destroyer - Aggro Line'),
(62068, 51, 0, 'Execute destruction measure 13.', 14, 0, 0, 0, 0, 0, 0, 0, 'Slagfist Destroyer - Dragonmaw Retreat - Slagfist Destroyer - 50% Health Line'),
(62068, 52, 0, 'Protocal failure...', 14, 0, 0, 0, 0, 0, 0, 0, 'Slagfist Destroyer - Dragonmaw Retreat - Slagfist Destroyer - Death Line'),
(62070, 50, 0, 'More Slaves? How fortunate for you to deliver yourself to me!', 14, 0, 0, 0, 0, 0, 0, 0, 'Overlord Blackheart - Dragonmaw Retreat - Overlord Blackheart - Aggro Line'),
(62070, 51, 0, 'Get into order, maggots!', 14, 0, 0, 0, 0, 0, 0, 0, 'Overlord Blackheart - Dragonmaw Retreat - Overlord Blackheart - 50% Health Line'),
(62070, 52, 0, 'Overlord Blackheart begins to laugh maniacally.', 16, 0, 0, 0, 0, 0, 0, 0, 'Overlord Blackheart - Dragonmaw Retreat - Overlord Blackheart - Death Line'),
(62071, 50, 0, 'I have been tasked to keep our sacred flame, do not test me!', 14, 0, 0, 0, 0, 0, 0, 0, 'Garlok Flamekeeper - Dragonmaw Retreat - Garlok Flamekeeper - Aggro Line'),
(62071, 51, 0, 'You have no place here!', 14, 0, 0, 0, 0, 0, 0, 0, 'Garlok Flamekeeper - Dragonmaw Retreat - Garlok Flamekeeper - 50% Health Line'),
(62071, 52, 0, 'My duty... Is failed...', 14, 0, 0, 0, 0, 0, 0, 0, 'Garlok Flamekeeper - Dragonmaw Retreat - Garlok Flamekeeper - Death Line');
